package com.hbm.client.reactor.rbmk.failure;
import java.util.Random;import com.hbm.client.model.*;import com.hbm.machine.reactor.rbmk.failure.DigammaSpear;import com.mojang.blaze3d.vertex.*;import com.mojang.math.Axis;import net.minecraft.client.Minecraft;import net.minecraft.client.renderer.*;import net.minecraft.client.renderer.entity.*;import net.minecraft.client.renderer.texture.OverlayTexture;import net.minecraft.resources.ResourceLocation;
/** Source RenderSpear: original lance model, +15Y/180X/2scale, white occupancy and seed432's 64 cumulative triangle fans. */
public final class DigammaSpearRenderer extends EntityRenderer<DigammaSpear> {
 private static final ResourceLocation MODEL=ResourceLocation.parse("hbm:models/weapons/lance.obj"),TEXTURE=ResourceLocation.parse("hbm:textures/models/weapons/lance.png");private static final MultiBufferSource.BufferSource BUFFERS=MultiBufferSource.immediate(new ByteBufferBuilder(262144));public DigammaSpearRenderer(EntityRendererProvider.Context context){super(context);shadowRadius=0;}@Override public ResourceLocation getTextureLocation(DigammaSpear entity){return TEXTURE;}
 @Override public void render(DigammaSpear spear,float yaw,float partial,PoseStack pose,MultiBufferSource ignored,int light){var mesh=LegacyObjModels.INSTANCE.get(Minecraft.getInstance().getResourceManager(),MODEL);pose.pushPose();pose.translate(0,15,0);pose.mulPose(Axis.XP.rotationDegrees(180));pose.scale(2,2,2);var base=RenderType.entityCutout(TEXTURE);LegacyObjRenderer.render(mesh,pose,BUFFERS.getBuffer(base),15728880,OverlayTexture.NO_OVERLAY,0xffffffff,LegacyObjRenderer.Convention.HFR,WavefrontMesh.legacyPart("Spear"));BUFFERS.endBatch(base);if(spear.ticksInGround>0){float occupancy=Math.min((spear.ticksInGround+partial)/100F,1);var white=BUFFERS.getBuffer(RbmkFailureRenderTypes.WHITE);for(var triangle:mesh.triangles()){var face=mesh.faces().get(triangle.face());if(!face.legacyPart().equalsIgnoreCase("Spear"))continue;for(int corner:new int[]{triangle.first(),triangle.second(),triangle.third()}){var vertex=mesh.positions().get(face.corners().get(corner).position());white.addVertex(pose.last().pose(),vertex.x(),vertex.y(),vertex.z()).setColor(1F,1F,1F,occupancy);}}BUFFERS.endBatch(RbmkFailureRenderTypes.WHITE);flash((spear.ticksInGround+partial)/200D,pose);}pose.popPose();}
 private static void flash(double intensity,PoseStack pose){pose.scale(.2F,.2F,.2F);var random=new Random(432L);var out=BUFFERS.getBuffer(RbmkFailureRenderTypes.FLASH);pose.pushPose();for(int i=0;i<64;i++){pose.mulPose(Axis.XP.rotationDegrees(random.nextFloat()*360));pose.mulPose(Axis.YP.rotationDegrees(random.nextFloat()*360));pose.mulPose(Axis.ZP.rotationDegrees(random.nextFloat()*360));pose.mulPose(Axis.XP.rotationDegrees(random.nextFloat()*360));pose.mulPose(Axis.YP.rotationDegrees(random.nextFloat()*360));float length=(random.nextFloat()*20+5+10)*(float)(intensity*intensity*25),width=(random.nextFloat()*2+1+2)*(float)(intensity*intensity*25),alpha=(float)(intensity*intensity)*2;float[][] vertices={{(float)(-.866D*width),length,-.5F*width},{(float)(.866D*width),length,-.5F*width},{0,length,width},{(float)(-.866D*width),length,-.5F*width}};for(int triangle=0;triangle<3;triangle++){out.addVertex(pose.last().pose(),0,0,0).setColor(1F,.6F,.6F,alpha);for(int corner=triangle;corner<triangle+2;corner++){var vertex=vertices[corner];out.addVertex(pose.last().pose(),vertex[0],vertex[1],vertex[2]).setColor(1F,.6F,.6F,0F);}}}pose.popPose();BUFFERS.endBatch(RbmkFailureRenderTypes.FLASH);}
}
